// System Call: getresgid()

gid_t r_gid;
gid_t e_gid;
gid_t s_gid;
int status;

/* Pointers to store:
   Real GID, Effective GID, Saved Set GID */
status = getresgid(&r_gid, &e_gid, &s_gid);

if (status == 0) {
    /* Success */
} else {
    /* Error: check errno (e.g., EFAULT) */
}
